SELECT 
  (SUM(CASE WHEN eye_colour_id = 7 THEN 1 ELSE 0 END) * 100.0) / COUNT(*) AS percentage
FROM superhero;

SELECT 
  (CAST(SUM(CASE WHEN language = 'Chinese Simplified' THEN 1 ELSE 0 END) AS REAL) / COUNT(*)) * 100 
FROM foreign_data;

SELECT 
  (CAST(SUM(CASE WHEN language = 'Chinese Simplified' THEN 1 ELSE 0 END) AS REAL) / COUNT(DISTINCT uuid)) * 100 
FROM foreign_data;

SELECT 
  (CAST(SUM(CASE WHEN language = 'Chinese Simplified' THEN 1 ELSE 0 END) AS REAL) / COUNT(id)) * 100 
FROM foreign_data;
